<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';o2oCsrfToken();requireLogin('vendor','login.php');$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){o2oRequireCsrf();$reviewId=(int)($_POST['review_id']??0);$response=trim((string)($_POST['vendor_response']??''));if($reviewId>0){$db->prepare("UPDATE reviews r JOIN items i ON i.id=r.item_id SET r.vendor_response=?,r.vendor_responded_at=CASE WHEN ?='' THEN NULL ELSE NOW() END WHERE r.id=? AND (r.vendor_id=? OR i.vendor_id=?)")->execute([$response,$response,$reviewId,$vendorId,$vendorId]);}header('Location: reviews.php');exit;}
$st=$db->prepare("SELECT r.id,r.rating,r.review,r.vendor_response,r.vendor_responded_at,r.created_at,c.name customer_name,i.name item_name FROM reviews r JOIN customers c ON c.id=r.customer_id LEFT JOIN items i ON i.id=r.item_id WHERE (r.vendor_id=? OR (r.vendor_id IS NULL AND i.vendor_id=?)) ORDER BY r.created_at DESC LIMIT 200");$st->execute([$vendorId,$vendorId]);$reviews=$st->fetchAll();
$avg=0;if($reviews){$sum=0;foreach($reviews as $r)$sum+=(int)$r['rating'];$avg=$sum/count($reviews);}
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ratings & Reviews – O2O Tradition</title><style>body{font-family:Arial;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:900px;margin:auto;padding:30px}.summary,.card{background:#fff;border:1px solid #DDE5DD;padding:20px;margin-bottom:15px}.rating{color:#8B1A1A;font-size:22px}.meta{font-size:12px;color:#777}.review{border-top:1px solid #eee;padding:16px 0}.review:first-child{border-top:0}</style></head><body><div class="nav"><b>O2O Tradition · Ratings</b><div><a href="dashboard.php">Dashboard</a><a href="notifications.php">Notifications</a><a href="logout.php">Logout</a></div></div><main class="main"><h1>Ratings & Reviews</h1><section class="summary"><div class="rating"><?=number_format($avg,2)?> / 5</div><div class="meta"><?=count($reviews)?> review(s) visible for your store/products.</div></section><section class="card"><?php foreach($reviews as $r):?><div class="review"><b><?=str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating'])?></b> · <?=htmlspecialchars($r['item_name']??'Store review')?><p><?=nl2br(htmlspecialchars($r['review']??''))?></p><div class="meta"><?=htmlspecialchars($r['customer_name'])?> · <?=date('d M Y, h:i A',strtotime($r['created_at']))?></div></div><form method="POST" style="margin-top:10px"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['csrf_token'])?>"><input type="hidden" name="review_id" value="<?=$r['id']?>"><textarea name="vendor_response" rows="3" maxlength="2000" style="width:100%;box-sizing:border-box;padding:8px" placeholder="Reply to this customer review"><?=htmlspecialchars($r['vendor_response']??'')?></textarea><button style="margin-top:6px;padding:8px 12px">Save Response</button></form></div><?php endforeach;if(!$reviews):?><p>No reviews yet.</p><?php endif;?></section></main></body></html>